    "targetQuery": "ai engineer roadmap",
    "image": "/blog/covers/ai-engineer-roadmap.webp",
    "imageAlt": "An open notebook full of hand-drawn sketches and notes with a wooden pen resting on the page",
    "author": "Umair",
